+package graph
+
+import (
+	"fmt"
+	"sort"
+	"strings"
+)
+
+var layerPatterns = []struct {
+	patterns    []string
+	name        string
+	description string
+}{
+	{patterns: []string{"routes", "controller", "handler", "endpoint", "api"}, name: "API Layer", description: "HTTP endpoints, route handlers, and API controllers"},
+	{patterns: []string{"service", "usecase", "use-case", "business"}, name: "Service Layer", description: "Business logic and application services"},
+	{patterns: []string{"model", "entity", "schema", "database", "db", "migration", "repository", "repo"}, name: "Data Layer", description: "Data models, database access, and persistence"},
+	{patterns: []string{"component", "view", "page", "screen", "layout", "widget", "ui"}, name: "UI Layer", description: "User interface components and views"},
+	{patterns: []string{"middleware", "interceptor", "guard", "filter", "pipe"}, name: "Middleware Layer", description: "Request and response middleware"},
+	{patterns: []string{"client", "integration", "external", "sdk", "vendor", "adapter"}, name: "External Services", description: "External integrations and SDK wrappers"},
+	{patterns: []string{"worker", "job", "queue", "cron", "consumer", "processor", "scheduler", "background"}, name: "Background Tasks", description: "Background workers and scheduled jobs"},
+	{patterns: []string{"util", "helper", "lib", "common", "shared"}, name: "Utility Layer", description: "Shared helpers and common libraries"},
+	{patterns: []string{"test", "spec", "__test__", "__spec__", "__tests__", "__specs__"}, name: "Test Layer", description: "Tests and test utilities"},
+	{patterns: []string{"config", "setting", "env"}, name: "Configuration Layer", description: "Configuration and environment settings"},
+}
+
+func detectLayers(nodes []GraphNode) []Layer {
+	layerMap := map[string][]string{}
+	for _, node := range nodes {
+		if node.Type != NodeTypeFile || node.FilePath == "" {
+			continue
+		}
+		layerName := matchLayer(node.FilePath)
+		layerMap[layerName] = append(layerMap[layerName], node.ID)
+	}
+
+	layers := make([]Layer, 0, len(layerMap))
+	for _, pattern := range layerPatterns {
+		if nodeIDs := layerMap[pattern.name]; len(nodeIDs) > 0 {
+			sort.Strings(nodeIDs)
+			layers = append(layers, Layer{
+				ID:          toLayerID(pattern.name),
+				Name:        pattern.name,
+				Description: pattern.description,
+				NodeIDs:     nodeIDs,
+			})
+		}
+	}
+	if nodeIDs := layerMap["Core"]; len(nodeIDs) > 0 {
+		sort.Strings(nodeIDs)
+		layers = append(layers, Layer{
+			ID:          toLayerID("Core"),
+			Name:        "Core",
+			Description: "Core application files",
+			NodeIDs:     nodeIDs,
+		})
+	}
+	return layers
+}
+
+func matchLayer(filePath string) string {
+	segments := strings.Split(strings.ToLower(strings.ReplaceAll(filePath, "\\", "/")), "/")
+	for _, pattern := range layerPatterns {
+		for _, segment := range segments {
+			for _, candidate := range pattern.patterns {
+				if segment == candidate || segment == candidate+"s" {
+					return pattern.name
+				}
+			}
+		}
+	}
+	return "Core"
+}
+
+func toLayerID(name string) string {
+	return fmt.Sprintf("layer:%s", strings.ToLower(strings.ReplaceAll(name, " ", "-")))
+}
+
+func generateHeuristicTour(graph *KnowledgeGraph) []TourStep {
+	nodeMap := make(map[string]GraphNode, len(graph.Nodes))
+	for _, node := range graph.Nodes {
+		nodeMap[node.ID] = node
+	}
+
+	nodeToLayer := map[string]Layer{}
+	for _, layer := range graph.Layers {
+		for _, nodeID := range layer.NodeIDs {
+			nodeToLayer[nodeID] = layer
+		}
+	}
+
+	tour := make([]TourStep, 0, len(graph.Layers))
+	seenLayers := map[string]struct{}{}
+	order := 1
+	for _, edge := range graph.Edges {
+		if edge.Type != EdgeTypeImports && edge.Type != EdgeTypeDependsOn {
+			continue
+		}
+		layer, ok := nodeToLayer[edge.Source]
+		if !ok {
+			continue
+		}
+		if _, exists := seenLayers[layer.ID]; exists {
+			continue
+		}
+		seenLayers[layer.ID] = struct{}{}
+		tour = append(tour, layerTourStep(order, layer, nodeMap))
+		order++
+	}
+	for _, layer := range graph.Layers {
+		if _, exists := seenLayers[layer.ID]; exists {
+			continue
+		}
+		seenLayers[layer.ID] = struct{}{}
+		tour = append(tour, layerTourStep(order, layer, nodeMap))
+		order++
+	}
+	return tour
+}
+
+func layerTourStep(order int, layer Layer, nodeMap map[string]GraphNode) TourStep {
+	keyFiles := make([]string, 0, min(5, len(layer.NodeIDs)))
