+type Pair struct {
+	Left  string
+	Right string
+}
+
+func normalizePair(a, b string) Pair {
+	if a > b {
+		a, b = b, a
+	}
+	return Pair{Left: a, Right: b}
+}
+
+func buildCochangePairs(paths []string) map[Pair]int {
+	unique := make([]string, 0, len(paths))
+	seen := map[string]struct{}{}
+	for _, path := range paths {
+		if _, ok := seen[path]; ok {
+			continue
+		}
+		seen[path] = struct{}{}
+		unique = append(unique, path)
+	}
+	sort.Strings(unique)
+
+	pairs := make(map[Pair]int)
+	for i := 0; i < len(unique); i++ {
+		for j := i + 1; j < len(unique); j++ {
+			pairs[normalizePair(unique[i], unique[j])]++
+		}
+	}
+	return pairs
+}
+
+func pairKey(a, b string) string {
+	pair := normalizePair(a, b)
+	return fmt.Sprintf("%s|%s", pair.Left, pair.Right)
+}
