+type FileMetrics struct {
+	CheckpointCount int
+	AgentCounts     map[string]int
+	LastCheckpoint  string
+	LastSessionID   string
+	LastPrompt      string
+	LastTouchedAt   time.Time
+}
+
+type Snapshot struct {
+	Files              map[string]*FileMetrics
+	CochangeCounts     map[string]int
+	ActiveSessionCount int
+}
+
+type Options struct {
+	Now        time.Time
+	WindowDays int
+}
+
+func Collect(ctx context.Context, opts Options) (*Snapshot, error) {
+	repo, err := strategy.OpenRepository(ctx)
+	if err != nil {
+		return nil, fmt.Errorf("open repository: %w", err)
+	}
+
+	v1Store := checkpoint.NewGitStore(repo)
+	v2URL, fetchErr := remote.FetchURL(ctx)
+	if fetchErr != nil {
+		v2URL = ""
+	}
+	v2Store := checkpoint.NewV2GitStore(repo, v2URL)
+
+	committed, err := listCommitted(ctx, v1Store, v2Store, settings.IsCheckpointsV2Enabled(ctx))
+	if err != nil {
+		return nil, fmt.Errorf("list checkpoints: %w", err)
+	}
+	sort.Slice(committed, func(i, j int) bool {
+		return committed[i].CreatedAt.After(committed[j].CreatedAt)
+	})
+
+	windowStart := opts.Now.AddDate(0, 0, -max(1, opts.WindowDays))
+	snapshot := &Snapshot{
+		Files:          map[string]*FileMetrics{},
+		CochangeCounts: map[string]int{},
+	}
+
+	for _, info := range committed {
+		if info.CreatedAt.Before(windowStart) {
+			continue
+		}
+
+		var prompt string
+		var sessionID string
+		if len(info.FilesTouched) > 0 {
+			if content, ok := readLatestContent(ctx, info.CheckpointID, v1Store, v2Store); ok {
+				prompt = extractPromptExcerpt(content.Prompts)
+				sessionID = content.Metadata.SessionID
+			}
+		}
+
+		agentName := string(info.Agent)
+		for _, path := range info.FilesTouched {
+			metrics, ok := snapshot.Files[path]
+			if !ok {
+				metrics = &FileMetrics{AgentCounts: map[string]int{}}
+				snapshot.Files[path] = metrics
+			}
+			metrics.CheckpointCount++
+			if agentName != "" {
+				metrics.AgentCounts[agentName]++
+			}
+			if metrics.LastTouchedAt.IsZero() || info.CreatedAt.After(metrics.LastTouchedAt) {
+				metrics.LastTouchedAt = info.CreatedAt
+				metrics.LastCheckpoint = info.CheckpointID.String()
+				metrics.LastSessionID = sessionID
+				metrics.LastPrompt = prompt
+			}
+		}
+
+		for pair, count := range buildCochangePairs(info.FilesTouched) {
+			snapshot.CochangeCounts[pairKey(pair.Left, pair.Right)] += count
+		}
+	}
+
+	states, err := strategy.ListSessionStates(ctx)
+	if err == nil {
+		snapshot.ActiveSessionCount = len(states)
+	}
+
+	return snapshot, nil
+}
+
+func listCommitted(ctx context.Context, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, preferV2 bool) ([]checkpoint.CommittedInfo, error) {
+	v1Committed, v1Err := v1Store.ListCommitted(ctx)
+	if !preferV2 {
+		return v1Committed, v1Err
+	}
+
+	v2Committed, v2Err := v2Store.ListCommitted(ctx)
+	if v2Err != nil {
+		return v1Committed, v1Err
+	}
+	if v1Err != nil {
+		return v2Committed, nil
+	}
+
+	seen := make(map[string]struct{}, len(v2Committed))
+	merged := make([]checkpoint.CommittedInfo, 0, len(v1Committed)+len(v2Committed))
+	for _, item := range v2Committed {
+		seen[item.CheckpointID.String()] = struct{}{}
+		merged = append(merged, item)
+	}
+	for _, item := range v1Committed {
+		if _, ok := seen[item.CheckpointID.String()]; ok {
+			continue
+		}
+		merged = append(merged, item)
+	}
+	return merged, nil
+}
+
+func readLatestContent(ctx context.Context, checkpointID checkpointid, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore) (*checkpoint.SessionContent, bool) {
+	reader, summary, err := checkpoint.ResolveCommittedReaderForCheckpoint(ctx, checkpoint.ID(checkpointID), v1Store, v2Store, true)
+	if err != nil || summary == nil || len(summary.Sessions) == 0 {
+		return nil, false
+	}
+	index := len(summary.Sessions) - 1
+	content, err := reader.ReadSessionContent(ctx, checkpoint.ID(checkpointID), index)
+	if err != nil {
+		return nil, false
+	}
+	return content, true
+}
+
+type checkpointid string
+
+func (c checkpointid) String() string {
+	return string(c)
+}
+
+func extractPromptExcerpt(raw string) string {
+	lines := strings.Split(raw, "\n")
+	for i := len(lines) - 1; i >= 0; i-- {
+		line := strings.TrimSpace(lines[i])
+		if line == "" {
+			continue
+		}
+		if len(line) > 120 {
+			return line[:120]
+		}
+		return line
+	}
+	return ""
+}
