+func analyzeGoFile(file sourceFile) ([]GraphNode, []importRef) {
+	fset := token.NewFileSet()
+	parsed, err := parser.ParseFile(fset, file.Path, file.Content, parser.ParseComments)
+	if err != nil {
+		return nil, nil
+	}
+
+	var nodes []GraphNode
+	var imports []importRef
+	for _, spec := range parsed.Imports {
+		importPath := strings.Trim(spec.Path.Value, `"`)
+		imports = append(imports, importRef{ImportPath: importPath})
+	}
+	for _, decl := range parsed.Decls {
+		switch typed := decl.(type) {
+		case *ast.FuncDecl:
+			name := typed.Name.Name
+			if typed.Recv != nil && len(typed.Recv.List) > 0 {
+				name = fmt.Sprintf("%s.%s", recvName(typed.Recv.List[0].Type), name)
+			}
+			nodes = append(nodes, GraphNode{
+				ID:         fmt.Sprintf("function:%s#%s", file.Path, name),
+				Type:       NodeTypeFunction,
+				Name:       name,
+				FilePath:   file.Path,
+				LineRange:  [2]int{fset.Position(typed.Pos()).Line, fset.Position(typed.End()).Line},
+				Summary:    "Go function or method.",
+				Tags:       []string{"go", "symbol"},
+				Complexity: complexityForLines(fset.Position(typed.End()).Line - fset.Position(typed.Pos()).Line + 1),
+			})
+		case *ast.GenDecl:
+			for _, spec := range typed.Specs {
+				typeSpec, ok := spec.(*ast.TypeSpec)
+				if !ok {
+					continue
+				}
+				switch typeSpec.Type.(type) {
+				case *ast.StructType, *ast.InterfaceType:
+					nodes = append(nodes, GraphNode{
+						ID:         fmt.Sprintf("class:%s#%s", file.Path, typeSpec.Name.Name),
+						Type:       NodeTypeClass,
+						Name:       typeSpec.Name.Name,
+						FilePath:   file.Path,
+						LineRange:  [2]int{fset.Position(typeSpec.Pos()).Line, fset.Position(typeSpec.End()).Line},
+						Summary:    "Go struct or interface.",
+						Tags:       []string{"go", "type"},
+						Complexity: complexityForLines(fset.Position(typeSpec.End()).Line - fset.Position(typeSpec.Pos()).Line + 1),
+					})
+				}
+			}
+		}
+	}
+	return nodes, imports
+}
+
+func analyzeScriptFile(file sourceFile) ([]GraphNode, []importRef) {
+	const importPattern = `(?m)^\s*import(?:[\s\w{},*]+from)?\s*["']([^"']+)["']|require\(\s*["']([^"']+)["']\s*\)`
+	const functionPattern = `(?m)^\s*(?:export\s+)?(?:async\s+)?function\s+([A-Za-z_][A-Za-z0-9_]*)|^\s*(?:const|let|var)\s+([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(?:async\s*)?\(`
+	const classPattern = `(?m)^\s*(?:export\s+)?class\s+([A-Za-z_][A-Za-z0-9_]*)`
+
+	imports := regexImports(file, regexp.MustCompile(importPattern))
+	nodes := regexSymbolNodes(file, regexp.MustCompile(functionPattern), NodeTypeFunction, "JavaScript or TypeScript function.")
+	nodes = append(nodes, regexSymbolNodes(file, regexp.MustCompile(classPattern), NodeTypeClass, "JavaScript or TypeScript class.")...)
+	return nodes, imports
+}
+
+func analyzePythonFile(file sourceFile) ([]GraphNode, []importRef) {
+	const importPattern = `(?m)^\s*from\s+([.\w]+)\s+import|^\s*import\s+([.\w, ]+)`
+	const functionPattern = `(?m)^def\s+([A-Za-z_][A-Za-z0-9_]*)`
+	const classPattern = `(?m)^class\s+([A-Za-z_][A-Za-z0-9_]*)`
+
+	imports := regexImports(file, regexp.MustCompile(importPattern))
+	nodes := regexSymbolNodes(file, regexp.MustCompile(functionPattern), NodeTypeFunction, "Python function.")
+	nodes = append(nodes, regexSymbolNodes(file, regexp.MustCompile(classPattern), NodeTypeClass, "Python class.")...)
+	return nodes, imports
+}
+
+func regexImports(file sourceFile, re *regexp.Regexp) []importRef {
+	matches := re.FindAllStringSubmatch(file.Content, -1)
+	imports := make([]importRef, 0, len(matches))
+	for _, match := range matches {
+		for i := 1; i < len(match); i++ {
+			value := strings.TrimSpace(match[i])
+			if value == "" {
+				continue
+			}
+			if strings.Contains(value, ",") {
+				for _, part := range strings.Split(value, ",") {
+					part = strings.TrimSpace(part)
+					if part != "" {
+						imports = append(imports, importRef{ImportPath: part})
+					}
+				}
+				continue
+			}
+			imports = append(imports, importRef{ImportPath: value})
+		}
+	}
+	return imports
+}
