+func regexSymbolNodes(file sourceFile, re *regexp.Regexp, nodeType NodeType, summary string) []GraphNode {
+	indexes := re.FindAllStringSubmatchIndex(file.Content, -1)
+	nodes := make([]GraphNode, 0, len(indexes))
+	for _, idx := range indexes {
+		name := ""
+		for group := 2; group < len(idx); group += 2 {
+			start := idx[group]
+			end := idx[group+1]
+			if start >= 0 && end > start {
+				name = file.Content[start:end]
+				break
+			}
+		}
+		if name == "" {
+			continue
+		}
+		line := lineNumberAtOffset(file.Content, idx[0])
+		nodes = append(nodes, GraphNode{
+			ID:         fmt.Sprintf("%s:%s#%s", nodeType, file.Path, name),
+			Type:       nodeType,
+			Name:       name,
+			FilePath:   file.Path,
+			LineRange:  [2]int{line, line},
+			Summary:    summary,
+			Tags:       []string{file.Language, "symbol"},
+			Complexity: "simple",
+		})
+	}
+	return nodes
+}
+
+func resolveImports(graph *KnowledgeGraph, imports []importRef, fileNodeIndex map[string]int, dirToFiles map[string][]string, modulePath string) {
+	added := map[string]struct{}{}
+	for _, ref := range imports {
+		targets := resolveImportTargets(ref, fileNodeIndex, dirToFiles, modulePath)
+		for _, target := range targets {
+			key := ref.SourceNodeID + "->" + target
+			if _, ok := added[key]; ok {
+				continue
+			}
+			added[key] = struct{}{}
+			graph.Edges = append(graph.Edges, GraphEdge{
+				Source:      ref.SourceNodeID,
+				Target:      target,
+				Type:        EdgeTypeImports,
+				Direction:   "forward",
+				Description: "Static import dependency",
+				Weight:      0.85,
+			})
+		}
+	}
+}
+
+func resolveImportTargets(ref importRef, fileNodeIndex map[string]int, dirToFiles map[string][]string, modulePath string) []string {
+	switch ref.Language {
+	case "go":
+		if modulePath != "" && strings.HasPrefix(ref.ImportPath, modulePath+"/") {
+			dir := strings.TrimPrefix(ref.ImportPath, modulePath+"/")
+			if files := dirToFiles[dir]; len(files) > 0 {
+				return fileIDs(files)
+			}
+		}
+	case "typescript":
+		if strings.HasPrefix(ref.ImportPath, ".") {
+			baseDir := filepath.Dir(ref.SourcePath)
+			candidate := filepath.Clean(filepath.Join(baseDir, ref.ImportPath))
+			for _, suffix := range []string{"", ".ts", ".tsx", ".js", ".jsx", ".mjs", ".cjs", "/index.ts", "/index.tsx", "/index.js"} {
+				path := strings.TrimPrefix(candidate+suffix, "./")
+				if _, ok := fileNodeIndex[path]; ok {
+					return []string{"file:" + path}
+				}
+			}
+		}
+	case "python":
+		path := strings.ReplaceAll(ref.ImportPath, ".", "/")
+		for _, candidate := range []string{path + ".py", filepath.Join(path, "__init__.py")} {
+			if _, ok := fileNodeIndex[candidate]; ok {
+				return []string{"file:" + candidate}
+			}
+		}
+	}
+	return nil
+}
