+func applyTelemetry(graph *KnowledgeGraph, files []sourceFile, snapshot *telemetry.Snapshot) {
+	pathToFileNode := map[string]*GraphNode{}
+	symbolsByFile := map[string][]*GraphNode{}
+	for i := range graph.Nodes {
+		node := &graph.Nodes[i]
+		if node.FilePath == "" {
+			continue
+		}
+		if node.Type == NodeTypeFile || node.Type == NodeTypeConfig || node.Type == NodeTypeDocument || node.Type == NodeTypeTable || node.Type == NodeTypeSchema || node.Type == NodeTypePipeline || node.Type == NodeTypeService {
+			pathToFileNode[node.FilePath] = node
+			continue
+		}
+		symbolsByFile[node.FilePath] = append(symbolsByFile[node.FilePath], node)
+	}
+
+	type score struct {
+		path  string
+		score float64
+	}
+	scores := make([]score, 0, len(snapshot.Files))
+	for path, metrics := range snapshot.Files {
+		scoreValue := float64(metrics.CheckpointCount) + float64(len(metrics.AgentCounts))*1.5
+		scores = append(scores, score{path: path, score: scoreValue})
+	}
+	sort.Slice(scores, func(i, j int) bool {
+		return scores[i].score > scores[j].score
+	})
+	hotnessRanks := map[string]int{}
+	for i, item := range scores {
+		hotnessRanks[item.path] = i + 1
+	}
+
+	for _, file := range files {
+		metrics, ok := snapshot.Files[file.Path]
+		if !ok {
+			continue
+		}
+		meta := &EntireNode{
+			CheckpointCount30d: metrics.CheckpointCount,
+			Agents30d:          metrics.AgentCounts,
+			LastCheckpointID:   metrics.LastCheckpoint,
+			LastSessionID:      metrics.LastSessionID,
+			LastPromptExcerpt:  metrics.LastPrompt,
+			LastTouchedAt:      metrics.LastTouchedAt.Format(time.RFC3339),
+			HotnessRank:        hotnessRanks[file.Path],
+			OnboardingScore:    float64(metrics.CheckpointCount) + float64(len(file.SymbolIDs))*0.25,
+		}
+		if node := pathToFileNode[file.Path]; node != nil {
+			node.Entire = meta
+		}
+		for _, symbol := range symbolsByFile[file.Path] {
+			symbol.Entire = meta
+		}
+	}
+
+	for i := range graph.Edges {
+		edge := &graph.Edges[i]
+		if edge.Type != EdgeTypeImports && edge.Type != EdgeTypeDependsOn && edge.Type != EdgeTypeRelated {
+			continue
+		}
+		left := strings.TrimPrefix(edge.Source, "file:")
+		right := strings.TrimPrefix(edge.Target, "file:")
+		count := snapshot.CochangeCounts[telemetry.PairKey(left, right)]
+		if count < 2 {
+			continue
+		}
+		edge.Entire = &EntireEdge{CochangeCount30d: count}
+	}
+
+	for pairKey, count := range snapshot.CochangeCounts {
+		if count < 2 {
+			continue
+		}
+		parts := strings.Split(pairKey, "|")
+		if len(parts) != 2 {
+			continue
+		}
+		graph.Edges = append(graph.Edges, GraphEdge{
+			Source:      "file:" + parts[0],
+			Target:      "file:" + parts[1],
+			Type:        EdgeTypeRelated,
+			Direction:   "bidirectional",
+			Description: "Frequently changed together across recent checkpoints",
+			Weight:      clamp(float64(count)/10.0, 0.2, 0.95),
+			Entire:      &EntireEdge{CochangeCount30d: count},
+		})
+	}
+}
