+func buildDiffOverlay(ctx context.Context, repoRoot string, graph *KnowledgeGraph, files []sourceFile) *DiffOverlay {
+	cmd := exec.CommandContext(ctx, "git", "status", "--porcelain", "--untracked-files=all")
+	cmd.Dir = repoRoot
+	out, err := cmd.Output()
+	if err != nil {
+		return &DiffOverlay{}
+	}
+
+	fileNodeIDs := map[string]string{}
+	symbolsByFile := map[string][]string{}
+	for _, node := range graph.Nodes {
+		if node.FilePath == "" {
+			continue
+		}
+		switch node.Type {
+		case NodeTypeFile, NodeTypeConfig, NodeTypeDocument, NodeTypeTable, NodeTypeSchema, NodeTypePipeline, NodeTypeService:
+			fileNodeIDs[node.FilePath] = node.ID
+		default:
+			symbolsByFile[node.FilePath] = append(symbolsByFile[node.FilePath], node.ID)
+		}
+	}
+
+	changed := map[string]struct{}{}
+	scanner := bufio.NewScanner(strings.NewReader(string(out)))
+	for scanner.Scan() {
+		line := strings.TrimSpace(scanner.Text())
+		if len(line) < 4 {
+			continue
+		}
+		path := strings.TrimSpace(line[3:])
+		if idx := strings.Index(path, " -> "); idx >= 0 {
+			path = path[idx+4:]
+		}
+		if nodeID, ok := fileNodeIDs[path]; ok {
+			changed[nodeID] = struct{}{}
+		}
+		for _, symbolID := range symbolsByFile[path] {
+			changed[symbolID] = struct{}{}
+		}
+	}
+
+	neighbors := map[string]struct{}{}
+	for _, edge := range graph.Edges {
+		if _, ok := changed[edge.Source]; ok {
+			neighbors[edge.Target] = struct{}{}
+		}
+		if _, ok := changed[edge.Target]; ok {
+			neighbors[edge.Source] = struct{}{}
+		}
+	}
+	for nodeID := range changed {
+		delete(neighbors, nodeID)
+	}
+	return &DiffOverlay{
+		ChangedNodeIDs:  sortedSet(changed),
+		AffectedNodeIDs: sortedSet(neighbors),
+	}
+}
+
+func applyDiff(graph *KnowledgeGraph, diff *DiffOverlay) {
+	if diff == nil {
+		return
+	}
+	changed := make(map[string]struct{}, len(diff.ChangedNodeIDs))
+	for _, id := range diff.ChangedNodeIDs {
+		changed[id] = struct{}{}
+	}
+	affected := make(map[string]struct{}, len(diff.AffectedNodeIDs))
+	for _, id := range diff.AffectedNodeIDs {
+		affected[id] = struct{}{}
+	}
+
+	for i := range graph.Nodes {
+		node := &graph.Nodes[i]
+		if node.Entire == nil {
+			node.Entire = &EntireNode{}
+		}
+		if _, ok := changed[node.ID]; ok {
+			node.Entire.DiffStatus = "changed"
+			continue
+		}
+		if _, ok := affected[node.ID]; ok {
+			node.Entire.DiffStatus = "affected"
+		}
+	}
+}
