+	}
+	session.URL = fmt.Sprintf("http://%s/?token=%s", listener.Addr().String(), token)
+	session.server = &http.Server{
+		Handler: session.routes(),
+	}
+	go func() {
+		_ = session.server.Serve(listener)
+	}()
+
+	return session, nil
+}
