+func (s *ServerSession) routes() http.Handler {
+	mux := http.NewServeMux()
+	mux.HandleFunc("/", s.handleIndex)
+	mux.HandleFunc("/knowledge-graph.json", s.handleGraph)
+	mux.HandleFunc("/meta.json", s.handleMeta)
+	mux.HandleFunc("/diff-overlay.json", s.handleDiff)
+	mux.HandleFunc("/api/diff", s.handleDiff)
+	mux.HandleFunc("/api/file", s.handleFile)
+	mux.HandleFunc("/api/checkpoint", s.handleCheckpoint)
+	return mux
