+		return
+	}
+	path := strings.TrimSpace(r.URL.Query().Get("path"))
+	if path == "" {
+		http.Error(w, "Missing path", http.StatusBadRequest)
+		return
+	}
+	absPath := filepath.Join(s.repoRoot, filepath.Clean(path))
+	if !paths.IsSubpath(s.repoRoot, absPath) {
+		http.Error(w, "Not found", http.StatusNotFound)
+		return
+	}
+	content, err := os.ReadFile(absPath) //nolint:gosec // path checked against repo root
+	if err != nil {
