+		http.Error(w, "Not found", http.StatusNotFound)
+		return
+	}
+	content, err := reader.ReadSessionContent(r.Context(), checkpointID, len(summary.Sessions)-1)
+	if err != nil {
+		http.Error(w, "Not found", http.StatusNotFound)
+		return
+	}
